-- Deduplicate active Fleet alerts generated by the automatic alert engine.
-- Safe for DEV and PROD: only adds a partial unique index.

CREATE UNIQUE INDEX IF NOT EXISTS fleet_alerts_active_dedupe_idx
ON public.fleet_alerts (company_id, alert_type, reference_type, reference_id)
WHERE auto_resolved_at IS NULL
  AND reference_type IS NOT NULL
  AND reference_id IS NOT NULL;
